// One shape for every entry: the undo button (a Telegram callback_query), a typed
// message, or the daily schedule. Route by Action switches on the action field.
const j = $input.first().json;
const cb = j.callback_query || null;
const msg = j.message || j.edited_message || {};
const chatFrom = (cb && cb.message && cb.message.chat && cb.message.chat.id) || (msg.chat && msg.chat.id) || '';
const chat_id = String(chatFrom || j.admin_chat_id || '').trim();
if (!chat_id) {
  throw new Error('No chat id. Set admin_chat_id in the Config node so scheduled runs know where to send.');
}
// callback_data is "action|skill|ref" and stays under Telegram's 64 byte limit
const parts = String((cb && cb.data) || '').split('|');
return [{ json: {
  action: cb ? 'callback' : 'scheduled',
  ref: cb ? String(parts[2] || '') : '',
  callback_id: cb ? String(cb.id || '') : '',
  chat_id,
  language: String(j.language || 'en')
} }];

// Two entry points: the daily schedule and a Telegram message. Normalise both into
// one shape so every node downstream reads the same fields.
const e = $('Normalise Entry').first().json;
return [{ json: {
  source: e.action === 'scheduled' ? 'schedule' : 'invoke',
  chat_id: e.chat_id,
  language: e.language || 'en',
  run_at: new Date().toISOString()
} }];

const ctx = $('Prep Sweep Input').first().json;

// n8n's Gmail node returns RAW header strings (From / To / Subject), not the
// parsed objects the simple-mode docs suggest. Reading m.subject / m.to.value
// silently produced empty subjects and a domain of "example.com>" on the first
// real run, so the model was classifying on the sender and snippet alone.
const addrOf = s => {
  const t = String(s || '').trim();
  const m = t.match(/<([^>]+)>/);
  return (m ? m[1] : t).trim().toLowerCase();
};
const nameOf = s => {
  const t = String(s || '').trim();
  const m = t.match(/^\s*"?([^"<]*?)"?\s*</);
  return m ? m[1].trim() : '';
};
const domOf = a => (String(a).split('@')[1] || '').replace(/[>\s]/g, '');

let knownAddresses = new Set(), knownDomains = new Set();
try {
  for (const it of $('Fetch Sent Contacts').all()) {
    const m = it.json || {};
    for (const part of String(m.To || m.to || '').split(',')) {
      const a = addrOf(part);
      if (!a || !a.includes('@')) continue;
      knownAddresses.add(a);
      const d = domOf(a);
      if (d) knownDomains.add(d);
    }
  }
} catch (e) { /* no sent mail in range just makes the guard weaker */ }

const FREEMAIL = new Set(['gmail.com','googlemail.com','outlook.com','hotmail.com','yahoo.com',
  'icloud.com','me.com','web.de','gmx.de','gmx.net','t-online.de','proton.me','protonmail.com']);

const inbox = $('Fetch Inbox').all().map(i => i.json)
  .filter(m => m && m.id)
  .map(m => {
    const rawFrom = m.From || m.from || '';
    const addr = addrOf(rawFrom);
    const dom = domOf(addr);
    return {
      id: m.id, threadId: m.threadId || '',
      from_name: nameOf(rawFrom),
      from: addr, domain: dom,
      subject: String(m.Subject || m.subject || ''),
      snippet: String(m.snippet || '').replace(/﻿/g, '').slice(0, 400),
      // a freemail address only counts as known on an exact match, never by domain
      known: knownAddresses.has(addr) || (!!dom && !FREEMAIL.has(dom) && knownDomains.has(dom))
    };
  })
  .filter(m => m.subject || m.snippet);

// never spend a model call on mail from people he actually corresponds with
const candidates = inbox.filter(m => !m.known).slice(0, 40);

return [{ json: {
  ...ctx,
  checked: inbox.length,
  protected_count: inbox.length - candidates.length,
  known_contacts: knownAddresses.size,
  candidates,
  candidates_json: JSON.stringify(candidates.map((c, i) => ({
    i, from: c.from, name: c.from_name, subject: c.subject, snippet: c.snippet
  })), null, 1)
} }];

const ctx = $('Build Junk Payload').first().json;
const raw = $input.first().json.message?.content ?? $input.first().json;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
const verdicts = Array.isArray(parsed.verdicts) ? parsed.verdicts : [];

const byIndex = new Map(ctx.candidates.map((c, i) => [i, c]));
const MAX_PER_RUN = Number($('⚙️ Config').first().json.max_moves_per_run || 15);

// Moving real mail to Spam is the one action here that costs him something, so
// the bar is deliberately high: the model must say junk AND be confident, and
// anything it is unsure about stays in the inbox.
const junk = [];
let borderline = 0;   // said junk but not confident: these stay in the inbox
for (const v of verdicts) {
  const c = byIndex.get(Number(v.index));
  if (!c) continue;
  if (v.junk !== true) continue;
  if (String(v.confidence || '').toLowerCase() !== 'high') { borderline++; continue; }
  junk.push({ ...c, reason: String(v.reason || '').slice(0, 140) });
}
const moved = junk.slice(0, MAX_PER_RUN);
// Counted separately: the old code reported junk.length - moved.length, which only
// ever caught the MAX_PER_RUN overflow, so the "N more looked suspect" line could
// never fire for borderline mail even though that is what it claims to report.
const held_back = borderline + (junk.length - moved.length);

const key = 'k' + Date.now().toString(36).slice(-6) + Math.random().toString(36).slice(2, 5);

return moved.length
  ? moved.map(m => ({ json: {
      ...ctx, undo_key: key, junk_count: moved.length,
      skipped_low_confidence: held_back,
      id: m.id, threadId: m.threadId, from: m.from, from_name: m.from_name,
      subject: m.subject, reason: m.reason,
      ids_csv: moved.map(x => x.id).join(',')
    } }))
  : [{ json: { ...ctx, undo_key: '', junk_count: 0, ids_csv: '', skipped_low_confidence: held_back } }];

// Write the undo record BEFORE anything is moved. If the Gmail call or the
// Telegram send fails afterwards, he can still get his mail back.
const items = $input.all().map(i => i.json);
const first = items[0];
const store = $getWorkflowStaticData('global');

// self-expiring: drop anything older than 14 days so static data cannot grow forever
const cutoff = Date.now() - Number($('⚙️ Config').first().json.undo_window_days || 14) * 24 * 3600 * 1000;
for (const k of Object.keys(store)) {
  if (k.startsWith('email_junk_sweep_undo_') && (store[k]?.at || 0) < cutoff) delete store[k];
}

store['email_junk_sweep_undo_' + first.undo_key] = {
  at: Date.now(),
  chat_id: first.chat_id,
  language: first.language,
  messages: items.map(m => ({ id: m.id, from: m.from, subject: m.subject }))
};

return items.map(j => ({ json: j }));

const items = $('Stash Undo').all().map(i => i.json);
const c = items[0];
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const de = c.language === 'de';

const lines = items.map(m => {
  const who = esc(m.from_name || m.from);
  return `• <b>${who}</b> - ${esc(String(m.subject).slice(0, 70))}\n   <i>${esc(m.reason)}</i>`;
});

let body = (de
  ? `🧹 <b>${items.length} in den Spam verschoben</b>\n\n`
  : `🧹 <b>Moved ${items.length} to Spam</b>\n\n`) + lines.join('\n');

if (c.skipped_low_confidence > 0) {
  body += de
    ? `\n\n<i>${c.skipped_low_confidence} weitere sahen verdaechtig aus, waren aber nicht eindeutig. Die bleiben im Posteingang.</i>`
    : `\n\n<i>${c.skipped_low_confidence} more looked suspect but ${c.skipped_low_confidence === 1 ? "was" : "were"} not clear cut, so ${c.skipped_low_confidence === 1 ? "it" : "they"} stayed in your inbox.</i>`;
}
body += de
  ? `\n\n<i>${c.checked} geprueft, ${c.protected_count} von echten Kontakten uebersprungen. Gmail loescht Spam nach 30 Tagen.</i>`
  : `\n\n<i>Checked ${c.checked}, skipped ${c.protected_count} from people you actually write to. Gmail deletes spam after 30 days.</i>`;

const MAX = 3600;
if (body.length > MAX) {
  body = body.slice(0, MAX);
  const lastOpen = body.lastIndexOf('<');
  if (lastOpen > body.lastIndexOf('>')) body = body.slice(0, lastOpen);
  for (const t of ['b', 'i']) {
    const o = (body.match(new RegExp('<' + t + '(?:\\s[^>]*)?>', 'g')) || []).length;
    const cl = (body.match(new RegExp('</' + t + '>', 'g')) || []).length;
    for (let k = 0; k < o - cl; k++) body += '</' + t + '>';
  }
  body += '\n…(truncated)';
}

return [{ json: {
  chat_id: c.chat_id, language: c.language, text: body,
  undo_key: c.undo_key, source: c.source, checked: c.checked,
  junk_count: items.length,
  moved: items.map(m => `${m.from} | ${m.subject}`).join(' ;; ').slice(0, 900),
  preview: body.replace(/<[^>]+>/g, '').slice(0, 300),
  undo_label: de ? '↩️ Zurueck in den Posteingang' : '↩️ Undo, put them back',
  undo_cb: `jnkundo|email_junk_sweep|${c.undo_key}`
} }];

const c = $('Resolve Junk').first().json;
const de = c.language === 'de';
return [{ json: {
  chat_id: c.chat_id, language: c.language, source: c.source,
  checked: c.checked, junk_count: 0, moved: '',
  notify: c.source === 'invoke',
  text: de
    ? `🧹 Nichts zu tun. ${c.checked} Mails geprueft, nichts eindeutig Junk.`
    : `🧹 Nothing to do. Checked ${c.checked}, nothing was clearly junk.`,
  preview: 'no junk found'
} }];

const cb = $('Normalise Entry').first().json;
const ref = String(cb.ref || cb.callback_ref || '').trim();
const store = $getWorkflowStaticData('global');
const rec = store['email_junk_sweep_undo_' + ref];

if (!rec || !Array.isArray(rec.messages) || !rec.messages.length) {
  return [{ json: {
    chat_id: cb.chat_id, language: cb.language || 'en', found: false, id: '',
    text: (cb.language === 'de')
      ? '↩️ Diese Liste ist nicht mehr da (aelter als 14 Tage). In Gmail unter Spam stehen sie noch.'
      : '↩️ That list has expired (older than 14 days). They are still in Gmail under Spam if you want them back by hand.'
  } }];
}
return rec.messages.map(m => ({ json: {
  chat_id: rec.chat_id, language: rec.language || 'en', found: true,
  id: m.id, from: m.from, subject: m.subject, count: rec.messages.length, ref
} }));

const items = $('Recall Undo').all().map(i => i.json);
const first = items[0];
if (!first.found) return [{ json: { chat_id: first.chat_id, text: first.text } }];
const de = first.language === 'de';
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = items.slice(0, 15).map(m => `• ${esc(m.from)} - ${esc(String(m.subject).slice(0, 60))}`).join('\n');
return [{ json: {
  chat_id: first.chat_id, language: first.language,
  text: (de ? `↩️ <b>${items.length} zurueck im Posteingang</b>\n\n` : `↩️ <b>${items.length} back in your inbox</b>\n\n`) + list
} }];
